DB = CardDB()
def _make_state(*a, **k):
    # Wrap the real _make_state to PRE-STOCK both decks — the base state
    # starts with EMPTY decks, so any 'draw a card' / 'banish the top card'
    # effect silently no-ops and a correct card fails its assertion. 20
    # dummy cards per deck make those effects observable by default.
    st = _base_make_state(*a, **k)
    st.card_db = DB
    for pid in (1, 2):
        if len(st.players[pid].deck.cards) == 0:
            for _ in range(20):
                c = Card(slug='dummy_card', name='dummy', types=['Action']); c.owner = c.controller = pid
                st.players[pid].deck.cards.append(c)
    return st
def _card(slug, owner=1, **overrides):
    # Tolerate a slug that isn't a real card: the auditor sometimes builds a
    # generic setup/opponent card via _card('some_slug'). DB.get returns None
    # for those, and None.owner crashes the whole test (zero signal). Fall
    # back to a bare Card so the test can still exercise the card UNDER TEST.
    #
    # **overrides sets attributes on the built card (_card('x', cost=3),
    # pitch=1, power=4, defense=2, types=[...]). The auditor writes these to
    # express a legitimate precondition ('a card costing 3 in hand'); before
    # they were accepted the call raised TypeError and the sample was lost
    # for a reason unrelated to the card under test.
    base = DB.get(slug)
    if base is None:
        c = Card(slug=slug, name=slug, types=['Action'], owner=owner, controller=owner)
    else:
        c = copy.deepcopy(base); c.owner = c.controller = owner
    _ALIAS = {'attack_power': 'power', 'attack': 'power', 'base_attack': 'base_power',
              'defense_value': 'defense', 'pitch_power': 'pitch', 'pitch_value': 'pitch'}
    for k, v in overrides.items():
        setattr(c, _ALIAS.get(k, k), v)
    return c
def activate(state, card, player_id=1):
    # Real activation flow: pays the ability's cost array (e.g. 'Destroy this')
    # AND runs its effects. Use this for ACTIVATE/ACTION cards.
    from engine.actions import Action, ActionType
    from engine.play import apply_action
    p = state.players[player_id]; p.action_points = max(1, p.action_points)
    apply_action(state, Action(type=ActionType.ACTIVATE_CARD, player_id=player_id, card=card))
def attack(state, card, attacker=1):
    # Real combat: `card` attacks the opponent HERO. Fires ON_ATTACK and
    # recomputes attack_power. Returns state.combat (assert .attack_power for
    # pumps). NOTE: for a hero attack the engine leaves combat.attack_target
    # None (it is set only when the attack targets a permanent/ally); the
    # ATTACK_TARGET_IS_HERO condition relies on that, and 'defending hero'
    # effects resolve via the controller's opponent, not attack_target — so
    # do NOT set attack_target here.
    from engine.state import CombatState
    import engine.engine as _E
    bp = getattr(card, 'power', None) or getattr(card, 'base_power', None) or 0
    state.combat = CombatState(attacker_id=attacker, link_id=1, attack_power=bp, attack_card=card, keywords=[])
    state.combat.base_attack_power = bp
    dispatch(state, 'ON_ATTACK', card.slug, card=card, event=None)
    _E._recalculate_attack_power(state)
    return state.combat
def hit(state, damage=None, **kw):
    # The current attack hits -> fires ON_HIT for the attacking card.
    # `damage`/`amount` set the attack's power first, so a test for an
    # 'if this deals 4 or more damage' clause can stage that precondition
    # instead of raising TypeError on an unexpected kwarg.
    dmg = damage if damage is not None else kw.get('amount')
    if dmg is not None:
        state.combat.attack_power = dmg
    ac = state.combat.attack_card; state.combat.hit = True
    dispatch(state, 'ON_HIT', ac.slug, card=ac, event=None)
def stock_deck(state, pid, n=20, **attrs):
    # Add more dummy cards to a deck (decks are pre-stocked with 20 already).
    # **attrs set attributes on each stocked card (color='yellow', pitch=3,
    # card_type='Arrow'), so 'reveal a yellow card' style preconditions are
    # expressible; unknown kwargs used to raise TypeError and lose the sample.
    _ALIAS = {'card_type': 'types', 'type': 'types', 'pitch_power': 'pitch'}
    for _ in range(n):
        c = Card(slug='dummy_card', name='dummy', types=['Action']); c.owner = c.controller = pid
        for k, v in attrs.items():
            k = _ALIAS.get(k, k)
            setattr(c, k, [v] if k == 'types' and isinstance(v, str) else v)
        state.players[pid].deck.cards.append(c)
    return state.players[pid].deck.cards
def set_turn_flag(state, pid, marker):
    # Stage a turn-scoped precondition the REAL way. The engine has no
    # `state.flags` / `player.flags` dict (44 + 18 recorded gate failures
    # invented one); turn state lives in `player.current_turn_effects` as
    # lowercase string markers written by the canonical keyword functions.
    state.players[pid].current_turn_effects.append(str(marker).lower())
def give_token(state, pid, slug, n=1):
    # Put n copies of a token under a player via the real create path, so
    # 'if you control a X token' conditions see them. Slugs are LOWERCASE
    # ('might', 'gold', 'seismic_surge'). Do NOT invent a *_token_count attr.
    if getattr(state, 'card_db', None) is None: state.card_db = DB
    from engine.effect_keywords import create_token
    create_token(state, pid, slug, n)


