def test_argh_smash_yellow_play_destroy_items():
    st = _make_state(); st.card_db = DB
    card = _card("argh_smash_yellow")
    st.players[1].arsenal.cards.append(card)
    
    # Set up opponent with items to destroy
    opponent_item = _card("item", cost=0)
    st.players[2].permanents.cards.extend([opponent_item])
    
    # Ensure deck has cards for rolling
    stock_deck(st, 1, n=1, color="yellow")
    
    # Capture before state
    before_items = len(st.players[2].permanents.cards)
    
    # Play the card
    dispatch(st, "ON_PLAY", "argh_smash_yellow", card=card, event=None)
    
    # After rolling and destroying items, assert that items were destroyed
    after_items = len(st.players[2].permanents.cards)
    
    # The number of items destroyed should be half the die roll (rounded down)
    # Since we're not mocking the die roll, just check that it's a valid destruction
    assert after_items <= before_items
    assert after_items >= before_items - 3  # Max possible destruction is 3 (if die roll = 6)


